    print("Top planar +Y candidates (top 6):")
    for i, t in enumerate(top_cands[:6]):
        print(f"  {i}: area={t[1]:.1f} centerY={t[2]:.3f} yRange=[{t[3]:.3f},{t[4]:.3f}]")

    print("Bottom planar -Y candidates (top 6):")
    for i, t in enumerate(bot_cands[:6]):
        print(f"  {i}: area={t[1]:.1f} centerY={t[2]:.3f} yRange=[{t[3]:.3f},{t[4]:.3f}]")

    if not top_cands or not bot_cands:
        print("ERROR: Could not find suitable top/bottom planar faces with normals ~±Y")
        return cq.Workplane(obj=shape)

    top_face = top_cands[0][0]
    bot_face = bot_cands[0][0]

    # --- Slot pattern parameters ---
    slot_len = 22.0     # mm
    slot_w = 6.0        # mm
    cut_depth = 2.0     # mm
    edge_margin = 16.0  # mm
    gap_z = 14.0        # mm gap between slots along Z
    pitch_z = slot_len + gap_z
    pitch_x = 18.0      # mm (used only if there is enough width)

    def _slot_centers_for_face(face, tag=""):
        plane = _build_plane_on_face(face)
        fbb = face.BoundingBox()
        fc = face.Center()

        xSpan = fbb.xmax - fbb.xmin
        zSpan = fbb.zmax - fbb.zmin
        print(f"Face {tag} @Y={fc.y:.3f}: xSpan={xSpan:.3f} zSpan={zSpan:.3f} area={_area(face):.1f}")

        # Keepouts from circular edges lying on this face plane
        keepouts = _circle_keepouts_on_plane_y(fc.y, fbb, slot_w=slot_w, slot_len=slot_len)
        print(f"Face {tag}: detected {len(keepouts)} circle keepouts on plane")
        for i, (kx, kz, kr) in enumerate(keepouts[:6]):
            print(f"  keepout[{i}]: center=({kx:.3f},{kz:.3f}) r_keepout={kr:.3f}")

        # Compute safe extents so slots don't clip boundaries
        x0 = fbb.xmin + edge_margin + (slot_w / 2.0)
        x1 = fbb.xmax - edge_margin - (slot_w / 2.0)
        z0 = fbb.zmin + edge_margin + (slot_len / 2.0)
        z1 = fbb.zmax - edge_margin - (slot_len / 2.0)

        if z1 <= z0:
            print(f"Face {tag}: no Z room for slots after margins")
            return plane, []

        # X: if not enough width, use a single centered column
        if x1 <= x0:
            xs = [0.5 * (fbb.xmin + fbb.xmax)]
        else:
            xs = []
            x = x0
            while x <= x1 + 1e-6:
                xs.append(x)
                x += pitch_x
            if not xs:
                xs = [0.5 * (x0 + x1)]

        # Z rows
        zs = []
        z = z0
        while z <= z1 + 1e-6:
            zs.append(z)
            z += pitch_z

        pts_local = []
        skipped_keepout = 0

        for x in xs:
            for z in zs:
                blocked = False
                for (kx, kz, kr) in keepouts:
                    if math.hypot(x - kx, z - kz) < kr:
                        blocked = True
                        break
                if blocked:
                    skipped_keepout += 1
                    continue

                v_global = cq.Vector(x, fc.y, z)
                v_loc = plane.toLocalCoords(v_global)
                pts_local.append((v_loc.x, v_loc.y))

        print(f"Face {tag}: generated {len(pts_local)} centers (skipped {skipped_keepout} due to keepouts)")
        return plane, pts_local

    def _make_cutters_for_face(face, tag=""):
        plane, pts = _slot_centers_for_face(face, tag=tag)
        if not pts:
            return None

        w = cq.Workplane(plane).pushPoints(pts)
        # Slot along global Z (plane local Y) -> angle=90
        try:
            w = w.slot2D(slot_len, slot_w, angle=90)
        except TypeError:
            w = w.slot2D(slot_len, slot_w)

        cutters = w.extrude(-cut_depth, combine=False)
        return cutters

    base = cq.Workplane(obj=shape)

    top_cutters = _make_cutters_for_face(top_face, tag="TOP")
    bot_cutters = _make_cutters_for_face(bot_face, tag="BOTTOM")

    if top_cutters is None and bot_cutters is None:
        print("WARNING: No cutters created. Returning original shape.")
        return base

    try:
        if top_cutters is not None:
            base = base.cut(top_cutters)
        if bot_cutters is not None:
            base = base.cut(bot_cutters)
    except Exception as e:
        print(f"ERROR during boolean cut: {e}")
        return cq.Workplane(obj=shape)

    print("Slot pattern cut applied on top and bottom with circle-feature keepouts.")
    return base
